    return true;
}

public static void tick(MinecraftServer server) {
    if (server == null || JOURNEYS.isEmpty()) {
        return;
    }
    for (UUID playerUuid : new ArrayList<UUID>(JOURNEYS.keySet())) {
        Journey journey = JOURNEYS.get(playerUuid);
